// AI translates intent into the same validated actions as the command system.
(()=>{
 const $=s=>document.querySelector(s);let configured=false,enabled=read('wd-natural-voice',true),pending=null,failed=null,controller=null,inFlight=null;
 const button=document.createElement('button');button.id='natural-voice-settings';button.textContent='Natural voice · setup';$('.conversation-actions').append(button);
 const dialog=document.createElement('dialog');dialog.id='natural-voice-dialog';dialog.innerHTML='<button class="dialog-close" aria-label="Close natural voice settings">×</button><div class="eyebrow">SPEAK YOUR WAY</div><h2>No scripts to remember.</h2><p>Wispr transcribes your voice. AI interprets what you mean and uses the book’s tools. If the target is unclear, it asks a short question.</p><div class="natural-examples"><span>“Put a peach note here that says call Mum.”</span><span>“Can you move that brown note onto page four?”</span><span>“Get rid of the writing on these two pages, but keep my pictures.”</span></div><p id="natural-connection" role="status">Checking the local AI connection…</p><label class="natural-toggle"><input id="natural-enabled" type="checkbox"> Understand requests naturally</label><button id="natural-check" class="primary">Check connection</button><p class="natural-setup">Add OPENAI_API_KEY to the project’s local .env file, then check again. The key stays on the server. Your utterance and a small context summary (book titles, current page, selected item, and visible note/caption labels) are sent to OpenAI when natural mode is on. Media files and the full diary are not sent.</p><p>Exact “Diary…” commands still run locally. Turn this off to use local interpretation only. The website cannot start the external Wispr recorder.</p>';
 document.body.append(dialog);dialog.querySelector('.dialog-close').onclick=()=>dialog.close();button.onclick=()=>{dialog.showModal();check()};
 const question=document.createElement('div');question.id='natural-question';question.hidden=true;question.innerHTML='<span id="natural-question-text" role="status"></span><button id="natural-cancel">Cancel request</button><button id="natural-retry" hidden>Retry</button>';
 $('#diary-view').append(question);$('#natural-cancel').onclick=()=>cancel('Request cancelled. Your book was not changed.');$('#natural-retry').onclick=()=>{if(failed){const text=failed.text;window.diaryConversation.send(text)}};
 function show(text,retry=false){question.hidden=false;$('#natural-question-text').textContent=text;$('#natural-retry').hidden=!retry}
 function hide(){question.hidden=true}
 function feedback(text){$('#session-feedback').textContent=text}
 function cancel(message){controller?.abort();controller=null;pending=null;failed=null;hide();if(message)feedback(message)}
 function label(){button.textContent=configured&&enabled?'Natural voice · on':configured?'Natural voice · off':'Natural voice · setup';$('#natural-enabled').checked=enabled;$('#natural-enabled').disabled=!configured;const hint=$('.manual-header p');if(hint)hint.textContent=configured&&enabled?'Describe what you want naturally. The commands below are optional examples; “Diary…” phrases still work locally.':'Command mode: say “Diary, [action] [what or where].” Connect Natural voice to use your own wording.'}
 async function check(){try{const response=await fetch('/api/ai/status',{cache:'no-store'}),data=await response.json();configured=response.ok&&data.configured===true;$('#natural-connection').textContent=configured?'Server key configured · '+data.model:window.diaryDeployment?.staticHosting?'Natural AI understanding is not enabled on this website. Dictation and local book commands are available.':'AI is not connected yet. Add your key locally, then check again.'}catch{configured=false;$('#natural-connection').textContent=window.diaryDeployment?.staticHosting?'The AI connection is unavailable. You can still dictate, type, and use local book commands.':'The AI backend is unavailable. Start the site with Start Diary.cmd.'}label();return configured}
 $('#natural-check').onclick=check;$('#natural-enabled').onchange=e=>{enabled=e.target.checked;store('wd-natural-voice',enabled);cancel();label()};
 function context(){const book=activeBook(),items=pieces.map((p,index)=>({id:p.id,type:p.type,number:pieces.filter(x=>x.type===p.type).findIndex(x=>x.id===p.id)+1,color:p.color,label:(p.text||'').slice(0,160),page:book.activeSpread*2+(p.x+p.w/2<50?1:2)}));return{bookId:book.id,bookTitle:book.title,pageCount:book.spreads.length*2,currentPage:window.bookControls.currentPage(),selectedId:selected,writingTarget:window.diaryDictationTarget.capture().label,books:books.map(b=>({id:b.id,title:b.title})).slice(0,40),items:items.slice(0,40)}}
 function fingerprint(){return JSON.stringify([activeBook().id,activeBook().updated,activeBook().activeSpread,selected,diary,pieces.map(p=>[p.id,p.text,p.x,p.y,p.w,p.color,p.tilt])])}
 function validate(plan){if(!plan||!['write','act','clarify','unsupported'].includes(plan.intent)||!Array.isArray(plan.commands)||plan.commands.length>8)throw Error('The interpreter returned an invalid plan.');if(plan.intent!=='act'){if(plan.commands.length)throw Error('Unexpected actions in a non-action response.');return[]}
  if(!plan.commands.length)throw Error('The interpreter did not provide an action.');const allowed=new Set(window.diaryCommandCatalog.map(c=>c.kind));return plan.commands.map(command=>{if(typeof command!=='string'||!/^Diary, /i.test(command))throw Error('Unsupported command format.');const action=window.DiaryCommands.parse(command);if(!allowed.has(action.kind)||['unknown','invalid-edit'].includes(action.kind))throw Error('That request needs a feature the book does not support yet.');if(action.page!==undefined&&action.page!==null&&(!Number.isInteger(action.page)||action.page<1))throw Error('Invalid page number.');if(action.pages&&!action.pages.every(p=>Number.isInteger(p)&&p>0))throw Error('Invalid page numbers.');return action})
 }
 function retain(text){const input=$('#voice-command-input');if(!input.value.trim())input.value=text;store('wd-pending-flow',input.value);window.showDiaryInput?.()}
 async function resolve(text){
  if(!configured||!enabled)return{actions:window.DiaryCommands.split(text).map(window.DiaryCommands.parse)};
  if(/^(?:cancel|never mind|cancel (?:that|request)|diary[, ]+cancel)[.!?]*$/i.test(text.trim())){cancel();return{actions:[],message:'Request cancelled. Your book was not changed.'}}
  if(/^diary\b/i.test(text.trim())){pending=null;failed=null;hide();return{actions:window.DiaryCommands.split(text).map(window.DiaryCommands.parse)}}
  if(pending&&pending.bookId!==activeBook().id){cancel();return{actions:[],message:'The book changed. Please repeat your request for this book.'}}
  const stamp=fingerprint(),followup=pending?{original:pending.original,question:pending.question,reply:text}:null;
  feedback('Understanding your request…');button.classList.add('thinking');inFlight=text;controller=new AbortController();const requestController=controller,timeout=setTimeout(()=>requestController.abort(),30000);
  try{const response=await fetch('/api/ai/interpret',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text,context:context(),clarification:followup}),signal:requestController.signal});const plan=await response.json();if(!response.ok)throw Error(plan.error||'The interpreter could not connect.');if(fingerprint()!==stamp){pending=null;retain(text);show('The book changed while I was understanding. Your words are kept in Type; resend when ready.');return{actions:[],message:'The book changed; no AI action was applied.'}}
   const actions=validate(plan);failed=null;
   if(plan.intent==='clarify'||plan.intent==='unsupported'){pending=plan.intent==='clarify'?{original:followup?.original||text,question:plan.question,bookId:activeBook().id}:null;show(plan.question||'Please clarify what you want to change.');return{actions:[],message:plan.question}}
   if(plan.intent==='act'&&actions.some(a=>['clear-content','clear-writing','notes-all'].includes(a.kind)&&a.scope==='book')&&!/\b(?:book|journal|all (?:the )?pages)\b/i.test((followup?.original||'')+' '+text)){pending={original:followup?.original||text,question:'Do you mean this page, these two pages, or the whole book? And just the writing or all content?',bookId:activeBook().id};show(pending.question);return{actions:[],message:pending.question}}
   pending=null;hide();return{actions:plan.intent==='write'?[{kind:'dictate',text}]:actions};
  }catch(error){if(requestController.signal.aborted&&!controller)return{actions:[]};failed={text};retain(text);show((error.name==='AbortError'?'The AI service took too long.':error.message)+' Your words are kept in Type. Retry, edit them, or use an exact Diary command.',true);return{actions:[],message:'AI could not interpret that request. Nothing was changed; your words are kept.'};
  }finally{clearTimeout(timeout);button.classList.remove('thinking');if(controller===requestController)controller=null;inFlight=null}
 }
 window.naturalVoice={resolve,check,cancel,pause(){const text=inFlight;cancel();if(text)retain(text)},isEnabled:()=>configured&&enabled,validate,context};check();
})();
